const { z } = require('zod');

// --- extractJson (ported from n8n/schemas/extractJson.mjs) ---
function parseBalancedFrom(text, start) {
  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escape) escape = false;
      else if (ch === '\\') escape = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') inString = true;
    else if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) {
        try { return { value: JSON.parse(text.slice(start, i + 1)), end: i }; }
        catch (e) { return null; }
      }
    }
  }
  return null;
}
function extractJson(text) {
  const objects = [];
  let cursor = text.indexOf('{');
  while (cursor !== -1) {
    const parsed = parseBalancedFrom(text, cursor);
    if (parsed) { objects.push(parsed.value); cursor = text.indexOf('{', parsed.end + 1); }
    else { cursor = text.indexOf('{', cursor + 1); }
  }
  if (objects.length === 0) throw new Error('No JSON object found in skill output');
  return objects[objects.length - 1];
}

// --- schemas (ported from n8n/schemas/schemas.mjs) ---
const confidence = z.enum(['high', 'medium', 'low']);
const zohoId = z.string().regex(/^\d{15,}$/, 'must be a Zoho record id (15+ digits)');
const blankToNull = (max) => z.union([z.string().max(max), z.null()]).transform((v) => (v === null || v.trim() === '' ? null : v.trim())).nullable();

const MatchOutput = z.object({
  matchStatus: z.enum(['existing_contact', 'new_contact_existing_account', 'new_account', 'ambiguous']),
  matchConfidence: confidence.nullable().default(null),
  matchedZohoContactId: zohoId.nullable().default(null),
  matchedZohoContactName: blankToNull(300).default(null),
  matchedZohoContactEmail: blankToNull(320).default(null),
  matchedZohoContactPhone: blankToNull(64).default(null),
  matchedZohoContactTitle: blankToNull(300).default(null),
  matchedZohoAccountId: zohoId.nullable().default(null),
  matchedZohoAccountName: blankToNull(300).default(null),
  matchedZohoAccountLevel: z.enum(['district', 'school']).nullable().default(null),
  hasActiveOpportunity: z.boolean().nullable().default(null),
  activeOpportunityName: blankToNull(300).default(null),
  candidateMatches: z.array(z.object({
    type: z.enum(['account', 'contact']).optional(),
    zohoId: zohoId.optional(),
    name: z.string().max(300).optional(),
    score: z.number().optional(),
    level: z.enum(['district', 'school']).optional(),
  }).passthrough()).max(50).nullable().default(null),
  notes: blankToNull(4000).default(null),
  glanceSummary: blankToNull(400).default(null),
})
  .passthrough()
  .refine((o) => (o.matchedZohoAccountId === null) === (o.matchedZohoAccountName === null), { message: 'matchedZohoAccountId and matchedZohoAccountName must be set together or null together' })
  .refine((o) => (o.matchedZohoAccountId === null) === (o.matchedZohoAccountLevel === null), { message: 'matchedZohoAccountLevel must be set/null together with matchedZohoAccountId' })
  .refine((o) => (o.matchedZohoContactId === null) === (o.matchedZohoContactName === null), { message: 'matchedZohoContactId and matchedZohoContactName must be set together or null together' })
  .refine((o) => o.matchStatus !== 'existing_contact' || o.matchedZohoContactId !== null, { message: 'matchStatus=existing_contact requires a matchedZohoContactId' })
  .refine((o) => o.matchStatus !== 'new_contact_existing_account' || o.matchedZohoAccountId !== null, { message: 'matchStatus=new_contact_existing_account requires a matchedZohoAccountId' })
  .refine((o) => o.matchConfidence !== 'high' || o.matchedZohoAccountId !== null, { message: 'matchConfidence=high requires a matched account -- refusing to auto-approve an unmatched contact' });

const ResearchOutput = z.object({
  firstName: z.string(),
  lastName: z.string(),
  alternateDistrictNames: z.array(z.string().max(300)).max(20).default([]),
  alternateNameSpellings: z.array(z.string().max(200)).max(20).default([]),
  nameCorrectionConfidence: confidence.nullable().default(null),
  institutionLevel: z.enum(['central_office', 'specific_campus', 'unknown']).default('unknown'),
  institutionLevelCampusName: blankToNull(300).default(null),
  institutionLevelConfidence: confidence.default('low'),
  institutionLevelAsOfDate: blankToNull(40).default(null),
  titleFinding: blankToNull(300).default(null),
  titleFindingConfidence: confidence.nullable().default(null),
  titleFindingAsOfDate: blankToNull(40).default(null),
  researchConfidence: confidence,
  personVerified: z.boolean(),
  researchNotes: blankToNull(4000).default(null),
}).passthrough();

const IntentOutput = z.object({ contactIntent: z.enum(['hot', 'warm', 'cold']).nullable() });

const AttributionOutput = z.object({
  results: z.array(z.object({
    contactId: z.string().uuid(),
    excerpt: z.string().max(8000).optional(),
    notFound: z.literal(true).optional(),
  }).refine((r) => (r.excerpt === undefined) !== (r.notFound === undefined), { message: 'each result needs exactly one of excerpt or notFound' })).max(200).default([]),
});

const MAX_CONTACTS_PER_NOTE = 50;
const NoteExtractionOutput = z.object({
  contacts: z.array(z.object({
    firstName: z.string().min(1).max(100),
    lastName: z.string().max(100),
    email: z.string().max(320).default(''),
    phone: z.string().max(40).default(''),
    title: z.string().max(200).default(''),
    districtName: z.string().max(200).default(''),
    schoolName: z.string().max(200).default(''),
    interactionNotes: z.string().max(4000).default(''),
    extractionConfidence: confidence,
  })).max(MAX_CONTACTS_PER_NOTE, 'a single note may not produce more than ' + MAX_CONTACTS_PER_NOTE + ' contacts -- split it into smaller pieces'),
  skipped: z.array(z.string().max(300)).max(50).default([]),
});

const CardExtractionSourceType = z.enum(['business_card', 'directory_listing']);
const CardExtractionOutput = z.object({
  status: z.enum(['ok', 'no_card_detected']),
  sourceImageHash: z.string().max(200).optional(),
  sourceType: CardExtractionSourceType.default('business_card'),
  cards: z.array(z.object({
    index: z.number().int().min(1).max(50),
    firstName: z.string().min(1).max(100),
    lastName: z.string().min(1).max(100),
    email: z.string().max(320).default(''),
    phone: z.string().max(40).default(''),
    title: z.string().max(200).default(''),
    districtName: z.string().max(200).default(''),
    schoolName: z.string().max(200).default(''),
    extractionConfidence: confidence,
    cropFileName: z.string().max(200).regex(/^[A-Za-z0-9._-]+$/, 'must be a bare filename, no path separators').nullable().default(null),
  })).max(50),
}).refine((o) => o.status === 'no_card_detected' || o.cards.length > 0, { message: 'status=ok requires at least one card' });

const SCHEMAS = { MatchOutput: MatchOutput, ResearchOutput: ResearchOutput, IntentOutput: IntentOutput, AttributionOutput: AttributionOutput, NoteExtractionOutput: NoteExtractionOutput, CardExtractionOutput: CardExtractionOutput };

const schemaName = $('Sub-workflow Input').item.json.schemaName;
const schema = SCHEMAS[schemaName];
if (!schema) {
  return [{ json: { success: false, error: 'unknown schemaName: ' + schemaName } }];
}

const anthropicItem = $input.first().json;
// n8n's Anthropic node output field name for the merged response text
// hasn't been confirmed against a live run yet (see the sticky note on
// this workflow) -- defensively try every shape it's plausibly under.
const rawText = typeof anthropicItem.content === 'string' ? anthropicItem.content
  : Array.isArray(anthropicItem.content) ? anthropicItem.content.map((b) => (b && b.text) || '').join('')
  : typeof anthropicItem.text === 'string' ? anthropicItem.text
  : typeof anthropicItem.output === 'string' ? anthropicItem.output
  : JSON.stringify(anthropicItem);

let parsed;
try { parsed = extractJson(rawText); }
catch (err) { return [{ json: { success: false, error: 'no JSON object found in model output: ' + err.message } }]; }

const result = schema.safeParse(parsed);
if (!result.success) {
  const issues = result.error.issues.map((i) => i.path.join('.') + ': ' + i.message).join('; ');
  return [{ json: { success: false, error: issues } }];
}
return [{ json: { success: true, data: result.data } }];
